class Solution:
    def minimumMoney(self, transactions):
        los = sorted([t for t in transactions if t[0] > t[1]], key=lambda t: t[1])
        gain = sorted([t for t in transactions if t[0] <= t[1]], key=lambda t: -t[0])
        need = have = 0
        for c, b in los + gain:
            need = max(need, have + c)
            have += c - b
        return need

