class Solution {
public:
    long long minimumMoney(vector<vector<int>>& transactions) {
        vector<vector<int>> los, gain;
        for (auto& t : transactions) (t[0] > t[1] ? los : gain).push_back(t);
        sort(los.begin(), los.end(), [](auto& a, auto& b){ return a[1] < b[1]; });
        sort(gain.begin(), gain.end(), [](auto& a, auto& b){ return a[0] > b[0]; });
        long long need = 0, have = 0;
        for (auto& t : los) { need = max(need, have + t[0]); have += t[0] - t[1]; }
        for (auto& t : gain) { need = max(need, have + t[0]); have += t[0] - t[1]; }
        return need;
    }
};

