class Solution {
    public long minimumMoney(int[][] transactions) {
        List<int[]> los = new ArrayList<>(), gain = new ArrayList<>();
        for (int[] t : transactions) (t[0] > t[1] ? los : gain).add(t);
        los.sort((a, b) -> a[1] - b[1]);
        gain.sort((a, b) -> b[0] - a[0]);
        long need = 0, have = 0;
        for (int[] t : los) { need = Math.max(need, have + t[0]); have += t[0] - t[1]; }
        for (int[] t : gain) { need = Math.max(need, have + t[0]); have += t[0] - t[1]; }
        return need;
    }
}

