class Solution {
public:
    long long minimumMoney(vector<vector<int>>& transactions) {
        long long L = 0, ans = 0;
        for (auto& t : transactions) L += max(0, t[0] - t[1]);
        for (auto& t : transactions)
            ans = max(ans, L - (long long)max(0, t[0] - t[1]) + t[0]);
        return ans;
    }
};

